      "pattern": "^[0-9a-f]{40}$",
      "$comment": "the commit Codex reviewed the repository at; MUST equal the brief's reviewed_head (40-hex git sha)."
    },
    "input_manifest_hash": {
      "type": "string",
      "pattern": "^sha256:[0-9a-f]{64}$",
      "$comment": "verbatim echo of the sealed brief's input_manifest_hash. Distinct from C3's codex_brief_hash concept — C0 has no separate 'brief' bundle; the input manifest IS what is sealed and echoed."
    },
    "review_status": {
      "type": "string",
      "enum": ["pass", "findings", "unverifiable"]
    },
    "unverifiable_reasons": {
      "type": "array",
      "minItems": 1,
      "items": {"type": "string", "minLength": 1},
      "$comment": "how the model reports 'could not complete the plan review' without inventing a field; conditionally required (see allOf)."
