    "blocking_findings": {
      "type": "boolean",
      "$comment": "Codex asserts this; the bridge cross-checks blocking_findings == (∃ crit/high finding) in jq — JSON-Schema cannot express that cross-field arithmetic."
    },
    "findings": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["severity", "area", "finding", "recommendation"],
        "properties": {
          "severity": {"type": "string", "enum": ["critical", "high", "medium", "low", "info"]},
          "area": {"type": "string", "minLength": 1},
          "finding": {"type": "string", "minLength": 1},
          "recommendation": {"type": "string", "minLength": 1},
          "action_owner": {"type": "string", "enum": ["implementer", "reviewer", "pm", "gate-fixer"]}
        },
        "allOf": [
          {
            "$comment": "action_owner is REQUIRED when severity is critical or high; optional (but still enum-constrained) otherwise. Fingerprint/occurrence_id are NOT here — those are bridge-added during normalize, exactly like C3's findings[], never emitted by the model itself.",
            "if": {
              "required": ["severity"],
              "properties": {"severity": {"enum": ["critical", "high"]}}
            },
            "then": {"required": ["action_owner"]}
          }
        ]
      }
    }
  },
  "allOf": [
    {
      "$comment": "unverifiable ⇒ unverifiable_reasons required (non-empty); forbidden otherwise.",
      "if": {
        "required": ["review_status"],
        "properties": {"review_status": {"const": "unverifiable"}}
      },
      "then": {"required": ["unverifiable_reasons"]},
      "else": {"not": {"required": ["unverifiable_reasons"]}}
    },
    {
      "$comment": "pass ⇒ no findings AND blocking_findings must be false.",
      "if": {
        "required": ["review_status"],
        "properties": {"review_status": {"const": "pass"}}
      },
      "then": {
        "properties": {
          "findings": {"maxItems": 0},
          "blocking_findings": {"const": false}
        }
      }
    },
    {
      "$comment": "findings ⇒ at least one finding.",
      "if": {
        "required": ["review_status"],
        "properties": {"review_status": {"const": "findings"}}
      },
      "then": {"properties": {"findings": {"minItems": 1}}}
    }
  ]
